&reftitle.description;

 public stringnullYaf_Request_Abstract::getLanguage


Obtém o idioma preferido do cliente

  &reftitle.examples;

   Exemplo de Yaf_Request_Abstract::getLanguage


<?php
class IndexController extends Yaf_Controller_Abstract
{
    public function indexAction()
    {
        // Supondo que o cliente envie "Accept-Language: zh-CN"
        $language = $this->getRequest()->getLanguage();

        var_dump($language);
    }
}
?>

   &example.outputs.similar;


string(5) "zh-CN"
